mapper.select:
SELECT COUNT(*) FROM rwd_grant_record
WHERE user_id = #{userId}
  AND prize_id = #{prizeId}
  AND status IN ('GRANTED', 'WON', 'CLAIMING', 'RETRY_PENDING')
  AND created_at >= #{from}

SELECT * FROM rwd_grant_record
WHERE grant_source = #{grantSource}
  AND source_id = #{sourceId}
  AND prize_id = #{prizeId}
LIMIT 1

mapper.update:
UPDATE rwd_grant_record
SET fulfillment_ref = #{fulfillmentRef}
WHERE id = #{id}
  AND fulfillment_ref IS NULL

mapper.select:
SELECT * FROM rwd_grant_record
WHERE status = 'RETRY_PENDING'
  AND next_retry_at <= #{now}
  AND (expire_at IS NULL OR expire_at > #{now})
ORDER BY next_retry_at ASC, id ASC
LIMIT #{limit}
